import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.egate.generictabcontent import GenericTabContent


class SgwStats(GenericTabContent):
    """SgwStats ecpsim command."""

    def __init__(
        self,
        connection,
        cmd_id,
        clear=False,
        stats_type=None,
        data_format=None,
        cmd_dir=None,
        data_iface=None,
        s1u_endpoint=None,
        s5u_endpoint=None,
        prompt=None,
        newline_chars=None,
        runner=None,
    ):
        """
        Get SGW statistics.

        :param connection: moler connection to device, terminal when command is executed
        :param cmd_id: local identifier of SGW
        :param clear: determine type of action on statistics: display or clear; default = display
        :param stats_type: statistics type, set of the following ,-separated:
         gtpu_endpoint - GTP-U Endpoint Statistics
         traffic      - Traffic Statistics (only for UEs for which these stats turned on - see bearer_sgw_param command)
         default = all
        :param data_format: format for output data; default = summary_long
         detail_short  - print common information on each item
         detail_long   - print detailed information on each item
         summary_short - print total common information for all items
         summary_long  - print total detailed information for all items
        :param cmd_dir: direction, possible values: ul, dl, bi; default = bi
        :param data_iface: gets the statistics for specified data interface, set of the following ,-separated:
         s1u - S1-U interface
         s5u - S5-U interface
         default = all
        :param s1u_endpoint: IP address and port of the S1-U endpoint. All S1-U endpoints if not specified.
         Format: a.a.a.a:p (:p), where a=0..255, p=0..65355.
        :param s5u_endpoint: IP address and port of the S5-U endpoint. All S1-U endpoints if not specified.
         Format: a.a.a.a:p (:p), where a=0..255, p=0..65355.
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SgwStats, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.cmd_id = cmd_id
        self.clear = clear
        self.stats_type = stats_type
        self.data_format = data_format
        self.cmd_dir = cmd_dir
        self.data_iface = data_iface
        self.s1u_endpoint = s1u_endpoint
        self.s5u_endpoint = s5u_endpoint

        self.current_ret["DICT"] = {}

        # private variables
        self._current_table_header = None
        self._headers_for_two_column_table = None
        self._headers_for_multicolumn_table = []
        self._is_multirow_table = False

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"sgw_stats id={self.cmd_id}"
        if self.clear:
            cmd = f"{cmd} clear"
        if self.stats_type:
            cmd = f"{cmd} type={self.stats_type}"
        if self.data_format:
            cmd = f"{cmd} format={self.data_format}"
        if self.cmd_dir:
            cmd = f"{cmd} dir={self.cmd_dir}"
        if self.data_iface:
            cmd = f"{cmd} data_iface={self.data_iface}"
        if self.s1u_endpoint:
            cmd = f"{cmd} s1u_endpoint={self.s1u_endpoint}"
        if self.s5u_endpoint:
            cmd = f"{cmd} s5u_endpoint={self.s5u_endpoint}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_not_configured_sgw(line)
                self._parse_current_device_info(line)
                self._parse_two_column_table_headers(line)
                self._parse_two_column_table_row(line)
                self._parse_headers(line)
                self._parse_vertical_table(line)
            except ParsingDone:
                pass
        return super(SgwStats, self).on_new_line(line, is_full_line)

    # is not configured
    _re_configured = re.compile(r"is not configured")

    def _parse_not_configured_sgw(self, line):
        if self._regex_helper.search_compiled(SgwStats._re_configured, line):
            self.set_exception(CommandFailure(self, f"Error: {line}"))
            raise ParsingDone

    # SGW-1, data_iface=s5u; dir=dl;
    _re_device_info = re.compile(r"(?P<DEVICE>SGW-\d+),\s+data_iface=(?P<IFACE>.*);\sdir=(?P<DIR>.*);")

    def _parse_current_device_info(self, line):
        if self._regex_helper.search_compiled(SgwStats._re_device_info, line):
            device = self._regex_helper.group("DEVICE")
            data_iface = self._regex_helper.group("IFACE")
            direction = self._regex_helper.group("DIR")
            self._current_table_header = (device, data_iface, direction)
            self._check_if_in_dict()
            self._headers_for_two_column_table = None
            self._headers_for_multicolumn_table = []
            raise ParsingDone

    def _parse_two_column_table_headers(self, line):
        row_divided_by_columns = re.split(r"\s{2,}", line)
        if len(row_divided_by_columns) == 2 and row_divided_by_columns[0] == "":
            self._headers_for_two_column_table = row_divided_by_columns[1]
            raise ParsingDone

    def _parse_two_column_table_row(self, line):
        row_divided_by_columns = re.split(r"\s{2,}", line)
        if len(row_divided_by_columns) == 2 and row_divided_by_columns[0] != "" and row_divided_by_columns[0] != "Parameter":
            two_column_table_value = row_divided_by_columns[1].split()
            row_dict = {row_divided_by_columns[0]: int(two_column_table_value[0])}
            self._parse_to_inter_table(row_dict)
            raise ParsingDone

    def _check_if_in_dict(self):
        if self._current_table_header:
            (device, data_iface, direction) = self._current_table_header
            if device in self.current_ret["DICT"]:
                if data_iface in self.current_ret["DICT"][device]:
                    if direction in self.current_ret["DICT"][device][data_iface]:
                        pass
                    else:
                        self.current_ret["DICT"][device][data_iface].update({direction: {}})
                else:
                    self.current_ret["DICT"][device].update({data_iface: {}})
                    self.current_ret["DICT"][device][data_iface].update({direction: {}})
            else:
                self.current_ret["DICT"].update({device: {}})
                self.current_ret["DICT"][device].update({data_iface: {}})
                self.current_ret["DICT"][device][data_iface].update({direction: {}})

    def _parse_to_inter_table(self, row_dict):
        (device, data_iface, direction) = self._current_table_header
        if self._headers_for_two_column_table:
            if self._headers_for_two_column_table in self.current_ret["DICT"][device][data_iface][direction]:
                self.current_ret["DICT"][device][data_iface][direction][self._headers_for_two_column_table].update(row_dict)
            else:
                self.current_ret["DICT"][device][data_iface][direction].update({self._headers_for_two_column_table: row_dict})
        else:
            self.current_ret["DICT"][device][data_iface][direction].update(row_dict)

    def _parse_headers(self, line):
        row_divided_by_columns = re.split(r"\s{2,}", line)
        if len(row_divided_by_columns) > 2 and not self._headers_for_multicolumn_table:
            if row_divided_by_columns[0].find("Traffic") > -1:
                self._is_multirow_table = True
                self._headers_for_multicolumn_table = row_divided_by_columns[1:]
            else:
                self._is_multirow_table = False
                self._headers_for_multicolumn_table = row_divided_by_columns

            self._headers_for_multicolumn_table = [header for header in self._headers_for_multicolumn_table if header]
            raise ParsingDone

    def _parse_vertical_table(self, line):
        row_divided_by_columns = re.split(r"\s{2,}", line)
        if len(row_divided_by_columns) > 2 and self._headers_for_multicolumn_table and self._is_multirow_table:
            traffic_type = row_divided_by_columns[0]
            row_dict = {traffic_type: dict(zip(self._headers_for_multicolumn_table, row_divided_by_columns[1:]))}
            (device, data_iface, direction) = self._current_table_header
            self.current_ret["DICT"][device][data_iface][direction].update(row_dict)
            raise ParsingDone
        elif len(row_divided_by_columns) > 2 and self._headers_for_multicolumn_table:
            row_dict = dict(zip(self._headers_for_multicolumn_table, row_divided_by_columns))
            (device, data_iface, direction) = self._current_table_header
            self.current_ret["DICT"][device][data_iface][direction].update(row_dict)
            raise ParsingDone


